class Solution { public int longestIncreasingPath(int[][] a) { int m=a.length,n=a[0].length;int[][] d=new int[m][n];ArrayDeque<int[]>q=new ArrayDeque<>();int[][] dirs={{1,0},{-1,0},{0,1},{0,-1}};for(int i=0;i<m;i++)for(int j=0;j<n;j++){for(int[] z:dirs){int x=i+z[0],y=j+z[1];if(x>=0&&x<m&&y>=0&&y<n&&a[x][y]<a[i][j])d[i][j]++;}if(d[i][j]==0)q.add(new int[]{i,j});}int len=0;while(!q.isEmpty()){len++;for(int k=q.size();k>0;k--){int[] u=q.remove();for(int[] z:dirs){int x=u[0]+z[0],y=u[1]+z[1];if(x>=0&&x<m&&y>=0&&y<n&&a[x][y]>a[u[0]][u[1]]&&--d[x][y]==0)q.add(new int[]{x,y});}}}return len;} }
